/**
 * /pages/About.jsx
 */

import React from 'react'
import { Card, Descriptions, Tag, Space, Typography, Divider } from 'antd'

import PageHeader from '@/components/PageHeader'
import { routes, resolveRedirect } from '@/router'
import { useI18n } from '@/lang'

const { Paragraph, Text } = Typography

/** Làm phẳng cây routes (kể cả route con) để hiển thị danh sách */
const flattenRoutes = (list, depth = 0) =>
  list.flatMap((r) => [
    { ...r, depth },
    ...(r.children ? flattenRoutes(r.children, depth + 1) : []),
  ])

const About = () => {
  const { t } = useI18n()

  return (
    <>
      <PageHeader
        title={t('Giới thiệu')}
        subtitle={t('Thông tin project và các thư viện sử dụng')}
      />

      <Card size="small" title={t('Thư viện')} className="mb-16">
        <Space wrap>
          <Tag color="blue">React 18</Tag>
          <Tag color="purple">Vite 5</Tag>
          <Tag color="cyan">Ant Design 5</Tag>
          <Tag color="green">Redux Toolkit</Tag>
          <Tag color="orange">React Router 6 (Hash)</Tag>
          <Tag color="red">Axios</Tag>
          <Tag color="gold">i18n (vi_VN / en_US / zh_TW)</Tag>
        </Space>
      </Card>

      <Card size="small" title={t('Danh sách routes đã khai báo')}>
        <Descriptions column={1} bordered size="small">
          {flattenRoutes(routes).map((r) => (
            <Descriptions.Item key={r.fullPath} label={r.fullPath}>
              <Space direction="vertical" size={0}>
                <Text strong>
                  {r.depth > 0 ? '↳ ' : ''}
                  {r.redirect !== undefined
                    ? t('Chuyển hướng')
                    : t(r.meta?.title || r.name)}
                </Text>
                <Text type="secondary" className="text-xs">
                  {r.redirect !== undefined ? (
                    <>
                      redirect → {resolveRedirect(r.redirect, r)}
                    </>
                  ) : (
                    <>
                      name: {r.name}
                      {r.meta?.requiresAuth ? ` • ${t('yêu cầu đăng nhập')}` : ''}
                    </>
                  )}
                </Text>
              </Space>
            </Descriptions.Item>
          ))}
        </Descriptions>
      </Card>

      <Divider />

      <Paragraph type="secondary">
        Router được khai báo tập trung tại <Text code>src/router/index.jsx</Text> theo
        phong cách vue-router: mảng <Text code>routes</Text> gồm{' '}
        <Text code>path / name / component / meta</Text>, kèm guard{' '}
        <Text code>beforeEach</Text> và các hook <Text code>useRouter()</Text> /{' '}
        <Text code>useRoute()</Text>.
      </Paragraph>

      <Paragraph type="secondary">
        Đa ngôn ngữ khai báo tại <Text code>src/lang/</Text> theo phong cách
        vue-i18n: từ điển <Text code>vi_VN.js / en_US.js / zh_TW.js</Text> với key là
        câu tiếng Việt, dùng qua <Text code>useI18n()</Text> →{' '}
        <Text code>t('Trang chủ')</Text>.
      </Paragraph>
    </>
  )
}

export default About
